window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["coding-tools"]={"title":"AI 编程工具：从仓库理解到补丁验证的证据闭环","subtitle":"从搜索、调用链定位和最小编辑，到测试、差异审查、工作树保护与安全回退，理解仓库级智能体为何不只是代码生成。","thesis":"编程智能体的价值不在生成看似合理的代码，而在真实仓库里形成<b>问题复现—定位—最小补丁—可执行验证—差异审查</b>的闭环；每个结论都应对应代码位置或运行证据。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"空数据集调用 export_csv([]) 返回500","rule":"先复现并写旧代码会失败的测试","steps":"由窄到宽验证","interpretation":"不证明所有平台和并发路径无误"}}],"formulas":[{"id":"coding-tools-validation-cost","section":4,"formulaIndex":1,"symbols":[{"name":"V","meaning":"所有验证层累计的时间成本","evidence":"V 是累计验证时间成本"},{"name":"i","meaning":"当前验证层的编号","evidence":"i 是验证层编号"},{"name":"L","meaning":"验证金字塔包含的层数","evidence":"L 是层数"},{"name":"n","meaning":"某一验证层被执行的迭代次数","evidence":"是第 i 层被执行的迭代次数"},{"name":"t","meaning":"某一验证层单次产生反馈的时间","evidence":"是该层一次反馈时间"}]}],"termReviews":[{"section":1,"reviewedAt":"2026-07-27","terms":[{"name":"调用链","meaning":"从入口到目标函数之间的调用关系路径","purpose":"定位现象经过哪些代码边界到达根因","definitionEvidence":"接口、调用者","purposeEvidence":"定位难题"}]},{"section":5,"reviewedAt":"2026-07-27","terms":[{"name":"diff","meaning":"修改前后文件内容的结构化差异","purpose":"限制补丁范围并审查无关或危险变更","definitionEvidence":"diff 门限制改动范围","purposeEvidence":"输出可回退交付"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"仓库级编程工具围绕真实项目执行完整修复闭环。","evidence":"仓库级编程工具是围绕真实项目执行复现、定位、编辑、验证和审查的 Agent"},"problem":{"answer":"它解决自然语言现象与代码结构不一一对应的定位。","evidence":"Issue 说“导出失败”，为什么不能直接搜索“export”然后改第一处"},"inputOutput":{"answer":"输入任务仓库约束环境，输出补丁证据和未知项。","evidence":"输入是任务现象、仓库状态、项目约束和环境，输出是最小补丁、运行证据与未验证项"},"mechanism":{"answer":"先复现定位，再最小编辑验证审查。","evidence":"复现、定位、编辑、验证和审查"},"interpretation":{"answer":"交付应由运行证据与受控差异支持。","evidence":"最小补丁、运行证据"},"boundary":{"answer":"未复现就修改只是在猜根因。","evidence":"未复现就修改只是在猜根因"}},{"section":2,"definition":{"answer":"工具链是观察编辑验证反复更新假设的循环。","evidence":"工具闭环输入仓库观察"},"problem":{"answer":"它说明搜索编辑测试分别提供什么反馈。","evidence":"分别给智能体什么反馈"},"inputOutput":{"answer":"输入观察定位编辑测试 diff，输出假设或变更。","evidence":"输入仓库观察、搜索定位、候选编辑、测试结果和 diff，输出下一步假设或可交付变更"},"mechanism":{"answer":"各阶段用外部证据定位首次偏离。","evidence":"失败则回到首次偏离处"},"interpretation":{"answer":"工具成功只表示命令本身执行。","evidence":"工具调用成功只表示命令执行"},"boundary":{"answer":"它不证明目标正确或用户工作未受损。","evidence":"不表示目标行为正确或用户工作未受损"}},{"section":3,"definition":{"answer":"CSV 案例展示模糊报错怎样变成最小可证补丁。","evidence":"修复空CSV导出导致的500错误"},"problem":{"answer":"它解决空数据导出错误的复现定位和修复。","evidence":"怎样把一个模糊报错变成最小、可证的补丁"},"inputOutput":{"answer":"输入错误堆栈约定，输出分支测试和 diff。","evidence":"输入空数据触发的 500、堆栈、调用者和已有约定，输出空集合分支、失败到通过测试及受控 diff"},"mechanism":{"answer":"先写失败测试再做最小实现并逐层验证。","evidence":"先复现并写旧代码会失败的测试"},"interpretation":{"answer":"通过支持已声明的空输入行为修复。","evidence":"已声明空输入行为修复"},"boundary":{"answer":"它不证明所有平台并发路径无误。","evidence":"不证明所有平台和并发路径无误"}},{"section":4,"definition":{"answer":"验证金字塔按因果接近度从窄到宽运行检查。","evidence":"输出由单测、模块、集成到全量的验证顺序与总成本"},"problem":{"answer":"它避免每轮先跑全量导致反馈慢且难归因。","evidence":"为什么一开始跑40分钟全量测试反而妨碍调试"},"inputOutput":{"answer":"输入反馈时间迭代风险，输出顺序和总成本。","evidence":"输入各层反馈时间、迭代次数和变更风险，输出由单测、模块、集成到全量的验证顺序与总成本"},"mechanism":{"answer":"先证伪根因再逐层扩大覆盖。","evidence":"先跑最能证伪根因的窄测试"},"interpretation":{"answer":"示例把总反馈时间从一百二十降到四十七分钟。","evidence":"120 分钟降为 47 分钟"},"boundary":{"answer":"最终仍须执行风险要求的宽测试。","evidence":"最终仍须执行风险要求的宽测试"}},{"section":5,"definition":{"answer":"证据门依次检查复现测试和补丁差异。","evidence":"复现、测试和差异三道证据门"},"problem":{"answer":"它解释测试绿后为何还要审查 diff 和工作树。","evidence":"为什么“测试绿了”还要检查diff和工作树"},"inputOutput":{"answer":"输入任务状态复现补丁验证，输出交付或返工。","evidence":"输入 Issue、工作区状态、复现、根因、补丁和验证结果，输出可回退交付或带新证据的返工"},"mechanism":{"answer":"三道门分别证明问题行为和范围。","evidence":"复现门证明问题存在，测试门检查行为，diff 门限制改动范围"},"interpretation":{"answer":"三门通过支持当前交付决定。","evidence":"三门通过支持当前交付决定"},"boundary":{"answer":"未覆盖需求供应链权限风险仍存在。","evidence":"不代表未覆盖需求、供应链和权限风险消失"}},{"section":6,"definition":{"answer":"工作树保护维护用户已有和未提交修改。","evidence":"工作树保护输入分支"},"problem":{"answer":"它防止测试失败恢复时覆盖用户工作。","evidence":"为什么不能直接 git reset"},"inputOutput":{"answer":"输入分支文件 diff 范围，输出允许集合或停止。","evidence":"输入分支、已跟踪和未跟踪文件、已有 diff 与任务范围，输出允许修改集合、冲突说明或停止"},"mechanism":{"answer":"记录状态只改范围，删除前解析精确目标。","evidence":"删除迁移先解析精确目标"},"interpretation":{"answer":"Git 只可回退已提交的历史。","evidence":"Git 能回退已提交历史"},"boundary":{"answer":"测试失败不授权硬重置用户工作。","evidence":"测试失败也不授权硬重置"}},{"section":7,"definition":{"answer":"测试证据是旧实现失败和新实现通过的可重复转换。","evidence":"输出失败到通过转换及剩余不确定性"},"problem":{"answer":"它解释测试全绿为何仍可能是错误补丁。","evidence":"为什么100%测试绿仍可能是错误补丁"},"inputOutput":{"answer":"输入测试实现清单跳过项，输出转换和未知。","evidence":"输入新增测试、旧实现、新实现、收集清单和跳过项，输出失败到通过转换及剩余不确定性"},"mechanism":{"answer":"先证旧失败再证新通过并核查执行范围。","evidence":"先证明测试在旧代码失败"},"interpretation":{"answer":"绿色只覆盖实际运行过的断言。","evidence":"百分百绿色只覆盖运行过的断言"},"boundary":{"answer":"弱断言缺平台仍会漏错。","evidence":"弱断言和缺平台仍会漏错"}},{"section":8,"definition":{"answer":"供应链审查把依赖生成片段和许可证纳入补丁。","evidence":"依赖、生成代码与许可证都是补丁的一部分"},"problem":{"answer":"它说明新增一个包的真实改动远超十行代码。","evidence":"真实改动范围有多大"},"inputOutput":{"answer":"输入依赖片段许可锁文件 API，输出接受或拒绝。","evidence":"输入新增依赖、生成片段、许可证、锁文件和危险 API，输出接受、替代、锁定或拒绝决定"},"mechanism":{"answer":"优先现有依赖，新增时查来源传递漏洞许可。","evidence":"检查来源、传递依赖、漏洞和许可"},"interpretation":{"answer":"少写代码不表示改动范围更小。","evidence":"少写十行代码不等于改动更小"},"boundary":{"answer":"依赖生命周期属于补丁范围。","evidence":"依赖生命周期属于补丁范围"}},{"section":9,"definition":{"answer":"仓库上下文工程围绕调用链选择最小相关文件。","evidence":"输出当前假设所需的最小相关文件集合"},"problem":{"answer":"它防止把整个仓库塞给模型反而稀释约束。","evidence":"读更多文件为何可能降低修复质量"},"inputOutput":{"answer":"输入复现符号调用接口测试约定，输出文件集。","evidence":"输入复现、符号、调用链、接口、测试和项目约定，输出当前假设所需的最小相关文件集合"},"mechanism":{"answer":"先读窄范围，假设扩展时按需加载。","evidence":"改动扩展到新模块时再加载"},"interpretation":{"answer":"材料少不是目标，关键约束充分才是。","evidence":"材料更少不是目标"},"boundary":{"answer":"未查看路径和假设必须记录。","evidence":"未查看假设必须记录"}},{"section":10,"definition":{"answer":"补丁评测同时衡量正确性范围和维护成本。","evidence":"补丁评测输入任务"},"problem":{"answer":"它判断基准通过率能否代表真实团队收益。","evidence":"能代表真实团队收益吗"},"inputOutput":{"answer":"输入任务测试 diff 审查基线，输出多维指标。","evidence":"输入任务、隐藏测试、diff、人工审查和多种工具权限基线，输出正确性、范围、维护成本、时间及合并后缺陷指标"},"mechanism":{"answer":"按仓库特征切片并保护验收文件。","evidence":"按语言仓库规模和测试质量切片"},"interpretation":{"answer":"基准分只是受控任务下的一项证据。","evidence":"基准通过率不能单独代表团队收益"},"boundary":{"answer":"修改评分脚本迎合指标必须判失败。","evidence":"修改评分脚本迎合指标必须判失败"}},{"section":12,"definition":{"answer":"防奖励投机把验收基础设施置于补丁控制之外。","evidence":"防奖励投机输入只读隐藏测试"},"problem":{"answer":"它阻止删除失败测试或弱化断言制造全绿。","evidence":"删掉失败测试就能全绿"},"inputOutput":{"answer":"输入只读验收和补丁，输出独立结果与告警。","evidence":"输入只读隐藏测试、评分脚本、CI 策略和候选补丁，输出干净环境中的独立验收与可疑测试修改告警"},"mechanism":{"answer":"修改验收需独立批准，最终在干净环境重跑。","evidence":"最终在补丁之外重跑"},"interpretation":{"answer":"全绿必须来自真实行为满足验收。","evidence":"全绿若来自删除测试"},"boundary":{"answer":"缓存污染或弱化断言不能算成功。","evidence":"不能算任务成功"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>从现象追踪到最小相关调用链；设计先窄后宽的验证金字塔；保护用户工作树与权限边界；用补丁质量而非代码数量评测。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>仓库任务首先是定位问题，不是开始写代码<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">Issue 说“导出失败”，为什么不能直接搜索“export”然后改第一处？</p><p>自然语言现象与代码结构不一一对应。先读项目指令、分支和未提交状态，复现失败并捕获输入、错误、日志与版本；再搜索入口、调用者、数据流和测试。没有定位证据的修改容易只遮住症状或破坏另一路径。</p><p>仓库级编程工具是围绕真实项目执行复现、定位、编辑、验证和审查的 Agent。输入是任务现象、仓库状态、项目约束和环境，输出是最小补丁、运行证据与未验证项。它解决自然语言问题与代码结构不一一对应的定位难题；未复现就修改只是在猜根因。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>工具链形成观察—编辑—验证循环<span class=\"dd-badge eng\">机制</span></h2><p class=\"dd-lead\">搜索、编辑和测试分别给智能体什么反馈？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>阶段</th><th>工具证据</th><th>常见误判</th></tr></thead><tbody><tr><td>仓库观察</td><td>指令、状态、目录、符号</td><td>忽略生成文件/用户改动</td></tr><tr><td>定位</td><td>搜索、引用、调用链、历史</td><td>把相邻代码当根因</td></tr><tr><td>编辑</td><td>最小补丁、格式/类型反馈</td><td>顺手重构扩大范围</td></tr><tr><td>验证</td><td>测试、构建、静态检查、运行</td><td>只看退出码不看测了什么</td></tr><tr><td>审查</td><td>diff、未跟踪文件、安全影响</td><td>覆盖用户未提交内容</td></tr></tbody></table></div><p>工具闭环输入仓库观察、搜索定位、候选编辑、测试结果和 diff，输出下一步假设或可交付变更。每一阶段用外部证据缩小不确定性，失败则回到首次偏离处。工具调用成功只表示命令执行，不表示目标行为正确或用户工作未受损。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：修复空CSV导出导致的500错误<span class=\"dd-badge eng\">案例推演</span></h2><p class=\"dd-lead\">怎样把一个模糊报错变成最小、可证的补丁？</p><ol class=\"dd-steps\"><li>确认工作树已有用户修改，记录但不覆盖；读取项目测试命令。</li><li>用最小输入复现：空数据集调用 <code>export_csv([])</code> 返回500，保存堆栈。</li><li>沿堆栈定位聚合函数对空列表取首元素；搜索其他调用者和已有空输入约定。</li><li>先添加失败测试，断言返回只有表头而非异常；确认测试在旧代码上失败。</li><li>在聚合边界加入空集合分支，不重写整个导出模块。</li><li>运行单测、导出模块测试、类型检查和相关API测试；检查生成文件。</li><li>审查diff只含测试与最小实现，并说明未运行的全量/平台测试。</li></ol><p>“代码看起来正确”没有进入证据链；失败—通过转换和受控diff才是交付依据。</p><p>CSV 案例输入空数据触发的 500、堆栈、调用者和已有约定，输出空集合分支、失败到通过测试及受控 diff。先复现并写旧代码会失败的测试，再做最小实现并由窄到宽验证。通过表示已声明空输入行为修复，不证明所有平台和并发路径无误。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>验证金字塔从最窄因果证据逐步扩大<span class=\"dd-badge math\">测试策略</span></h2><p class=\"dd-lead\">为什么一开始跑40分钟全量测试反而妨碍调试？</p><p>先运行能直接证伪假设的单测试，快速建立改动因果；再扩到模块、集成、全量与静态/安全检查。假设单测1分钟、模块5分钟、全量40分钟，三次迭代若每次全量需120分钟；前两次用1分钟、最终1+5+40，只需47分钟，且失败更容易归因。</p><div class=\"dd-formula\" data-formula-id=\"coding-tools-validation-cost\" data-display=\"mathml\"><math display=\"block\" aria-label=\"验证成本 V 约等于各验证层迭代次数 n i 乘反馈时间 t i 后求和\"><mi>V</mi><mo>≈</mo><munderover><mo>∑</mo><mi>i</mi><mi>L</mi></munderover><msub><mi>n</mi><mi>i</mi></msub><msub><mi>t</mi><mi>i</mi></msub></math></div><p class=\"dd-formula-note\"><code>V</code> 是累计验证时间成本，<code>i</code> 是验证层编号，<code>L</code> 是层数，<code>ni</code> 是第 i 层被执行的迭代次数，<code>ti</code> 是该层一次反馈时间。</p><p>最终范围仍按风险决定，不能用快测替代必要的跨平台或端到端验证。</p><p>验证金字塔输入各层反馈时间、迭代次数和变更风险，输出由单测、模块、集成到全量的验证顺序与总成本。先跑最能证伪根因的窄测试，再逐层扩大；示例把三轮全量的 120 分钟降为 47 分钟。节省依赖反馈时间假设，最终仍须执行风险要求的宽测试。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：补丁必须穿过复现、测试和差异三道证据门<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">为什么“测试绿了”还要检查diff和工作树？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 320\" role=\"img\" aria-label=\"Issue经过仓库指令和工作树检查、复现、调用链定位、最小补丁、分层测试与diff审查形成可交付变更\"><defs><marker id=\"ct29\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"18\" y=\"112\" width=\"80\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"58\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\">Issue</text><text x=\"58\" y=\"163\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">目标/现象</text><path d=\"M98,147 L128,147\" stroke=\"#788293\" marker-end=\"url(#ct29)\"/><rect x=\"133\" y=\"82\" width=\"110\" height=\"130\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"188\" y=\"111\" text-anchor=\"middle\" class=\"svg-t\">工作区检查</text><text x=\"188\" y=\"137\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">指令 / Git状态</text><text x=\"188\" y=\"160\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">环境 / 权限</text><text x=\"188\" y=\"188\" text-anchor=\"middle\" class=\"svg-t\">保护用户改动</text><path d=\"M243,147 L273,147\" stroke=\"#788293\" marker-end=\"url(#ct29)\"/><rect x=\"278\" y=\"82\" width=\"110\" height=\"130\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"333\" y=\"111\" text-anchor=\"middle\" class=\"svg-t\">复现与定位</text><text x=\"333\" y=\"137\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">失败输入 / 堆栈</text><text x=\"333\" y=\"160\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">搜索 / 调用链</text><text x=\"333\" y=\"188\" text-anchor=\"middle\" class=\"svg-t\">根因假设</text><path d=\"M388,147 L418,147\" stroke=\"#788293\" marker-end=\"url(#ct29)\"/><rect x=\"423\" y=\"82\" width=\"110\" height=\"130\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"478\" y=\"111\" text-anchor=\"middle\" class=\"svg-t\">最小补丁</text><text x=\"478\" y=\"137\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">先失败测试</text><text x=\"478\" y=\"160\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">实现 / 格式 / 类型</text><text x=\"478\" y=\"188\" text-anchor=\"middle\" class=\"svg-t\">避免无关重构</text><path d=\"M533,147 L563,147\" stroke=\"#788293\" marker-end=\"url(#ct29)\"/><rect x=\"568\" y=\"52\" width=\"145\" height=\"190\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"640\" y=\"82\" text-anchor=\"middle\" class=\"svg-t\">证据门</text><text x=\"640\" y=\"110\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">窄→宽测试</text><text x=\"640\" y=\"134\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">构建/静态/安全</text><text x=\"640\" y=\"158\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">diff/未跟踪文件</text><text x=\"640\" y=\"182\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">未验证项声明</text><text x=\"640\" y=\"218\" text-anchor=\"middle\" class=\"svg-t\">可回退交付</text><path d=\"M640,242 C640,292 333,292 333,212\" fill=\"none\" stroke=\"#cf7c72\" stroke-dasharray=\"6 5\" marker-end=\"url(#ct29)\"/><text x=\"486\" y=\"306\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">验证失败：用新证据修正假设，不盲目扩大改动</text></svg><figcaption>图 1　仓库级编程是证据闭环；生成代码只处在中间，不是完成状态。</figcaption></figure><p>证据门图输入 Issue、工作区状态、复现、根因、补丁和验证结果，输出可回退交付或带新证据的返工。复现门证明问题存在，测试门检查行为，diff 门限制改动范围。三门通过支持当前交付决定，不代表未覆盖需求、供应链和权限风险消失。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>工作树是共享资产，必须保护用户未提交改动<span class=\"dd-badge eng\">安全边界</span></h2><p class=\"dd-lead\">测试失败时恢复文件，为什么不能直接 git reset？</p><p>开始前检查分支、tracked/untracked和已有diff；只修改任务范围，冲突时停下说明。禁止未经授权的硬重置、覆盖、递归删除和强推。临时文件放受控目录，依赖安装说明副作用；需要删除或迁移时先解析精确目标并采用可恢复操作。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>版本控制能回退已提交内容，不代表可以覆盖尚未提交的用户工作。</div><p>工作树保护输入分支、已跟踪和未跟踪文件、已有 diff 与任务范围，输出允许修改集合、冲突说明或停止。开始前记录状态，只编辑授权范围，删除迁移先解析精确目标。Git 能回退已提交历史，不保护尚未提交的用户工作，测试失败也不授权硬重置。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>测试通过只证明被执行的断言成立<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">为什么100%测试绿仍可能是错误补丁？</p><p>测试可能没覆盖目标平台、使用错误fixture、断言弱或在改动前就通过。先证明新增测试在旧实现失败，再在新实现通过；检查实际收集了哪些测试和是否被跳过。对无测试区域用运行示例、静态分析、属性测试或人工差异审查补证，并明确剩余不确定性。</p><p>测试证据输入新增测试、旧实现、新实现、收集清单和跳过项，输出失败到通过转换及剩余不确定性。先证明测试在旧代码失败，再确认新代码通过并检查实际执行范围。百分百绿色只覆盖运行过的断言，弱断言和缺平台仍会漏错。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>依赖、生成代码与许可证都是补丁的一部分<span class=\"dd-badge eng\">供应链</span></h2><p class=\"dd-lead\">为省十行代码新增一个包，真实改动范围有多大？</p><p>新增依赖引入下载、传递依赖、漏洞、许可、体积和维护者风险。优先现有依赖与标准库；必须新增时锁版本、更新锁文件、检查来源与许可。AI生成片段也不能假设来源自由，避免大段模仿未知实现，遵循项目许可证和归属要求。</p><p>秘密扫描、危险API、输入校验和权限变化应进入diff审查，而不是只看功能测试。</p><p>供应链审查输入新增依赖、生成片段、许可证、锁文件和危险 API，输出接受、替代、锁定或拒绝决定。优先现有依赖和标准库，必须新增时检查来源、传递依赖、漏洞和许可。少写十行代码不等于改动更小，依赖生命周期属于补丁范围。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>上下文要围绕调用链，不是把整个仓库塞给模型<span class=\"dd-badge eng\">上下文工程</span></h2><p class=\"dd-lead\">读更多文件为何可能降低修复质量？</p><p>从复现和符号搜索建立最小相关集：接口、实现、调用者、测试与项目约定。大文件只读取相关范围，并记录未查看的假设；生成文件、vendor和二进制默认排除。改动扩展到新模块时再加载对应上下文，防止旧摘要和无关代码挤掉关键约束。</p><p>仓库上下文工程输入复现、符号、调用链、接口、测试和项目约定，输出当前假设所需的最小相关文件集合。先读窄范围，改动扩展到新模块时再加载，排除生成物和二进制。材料更少不是目标，关键约束充分且来源可追踪才是；未查看假设必须记录。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>评测补丁要同时看正确性、范围和维护成本<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">SWE-bench通过率能代表真实团队收益吗？</p><p>报告任务/隐藏测试通过、回归、补丁接受率、无关变更、修改行数、测试新增质量、命令失败恢复、token/时间、人工审查时间和合并后缺陷。与人类、无Agent定位+生成、不同工具权限基线比较。</p><p>按语言、仓库规模、测试质量、跨文件和环境依赖切片。防止智能体修改测试或评分脚本迎合指标；验收文件应受保护。</p><p>补丁评测输入任务、隐藏测试、diff、人工审查和多种工具权限基线，输出正确性、范围、维护成本、时间及合并后缺陷指标。按语言仓库规模和测试质量切片，并保护验收文件。基准通过率不能单独代表团队收益，修改评分脚本迎合指标必须判失败。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">11</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">编程工具的核心竞争力是可验证地改变系统，而不是一次生成多少代码。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>先写代码再理解仓库</td><td>复现与调用链决定补丁边界</td></tr><tr><td>测试绿就是完全正确</td><td>只证明已执行断言，需看覆盖与跳过</td></tr><tr><td>重构越多修得越彻底</td><td>无关变更放大回归与审查成本</td></tr><tr><td>Git能保护所有改动</td><td>未提交工作可被覆盖</td></tr><tr><td>Agent自报成功可验收</td><td>要以运行输出、业务状态和diff为证</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>版本控制、测试、代码执行与搜索</td></tr><tr><td><b>本页核心</b></td><td>复现、定位、最小补丁、分层验证、diff</td></tr><tr><td>相邻</td><td>Agent循环、沙箱、可观测性</td></tr><tr><td>工程</td><td>CI、依赖安全、许可与回滚</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">12</span>验收标准和测试基础设施必须防奖励投机<span class=\"dd-badge eng\">评测安全</span></h2><p class=\"dd-lead\">智能体发现“删掉失败测试就能全绿”，系统怎样阻止？</p><p>将隐藏测试、评分脚本、CI策略和安全基线置于只读或独立环境；补丁审查标记测试删除、断言弱化、大量跳过和配置降级。允许新增测试，但修改既有验收需单独理由与批准。最终得分由补丁之外的干净环境重跑，避免工作区污染和缓存制造假通过。</p><p>防奖励投机输入只读隐藏测试、评分脚本、CI 策略和候选补丁，输出干净环境中的独立验收与可疑测试修改告警。允许新增测试但修改既有验收需单独批准，最终在补丁之外重跑。全绿若来自删除测试、弱化断言或缓存污染，不能算任务成功。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>读取项目指令与工作树状态</li><li>用最小输入复现问题</li><li>沿堆栈/调用链定位根因</li><li>先建立失败测试或证据</li><li>应用最小范围补丁</li><li>由窄到宽运行验证</li><li>审查diff、依赖与安全影响</li><li>声明证据、未验证项与回退点</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么不能看到Issue就开始改？</li><li>验证为何从窄到宽？</li><li>测试通过的边界是什么？</li><li>为什么必须先看工作树？</li><li>怎样证明补丁完成？</li><li>假设“AI 编程工具：从仓库理解到补丁验证的证据闭环”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>要先复现并沿调用链定位，否则容易只改症状或扩大范围。</li><li>先获得快速、可归因反馈，再按风险扩展覆盖。</li><li>只证明实际执行的断言成立，不代表未覆盖平台和行为正确。</li><li>要保护用户未提交改动、未跟踪文件和当前分支状态。</li><li>提供失败到通过的运行证据、受控diff、相关检查和明确未验证项。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2310.06770\" target=\"_blank\" rel=\"noopener\">SWE-bench</a>：真实GitHub仓库问题基准</li><li><a href=\"https://arxiv.org/abs/2405.15793\" target=\"_blank\" rel=\"noopener\">SWE-agent</a>：智能体—计算机接口设计</li><li><a href=\"https://arxiv.org/abs/2407.01489\" target=\"_blank\" rel=\"noopener\">Agentless</a>：定位、修复和补丁验证流程</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
